pdate_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(id AS CHAR),20,'0')),CAST(`marketCode` AS CHAR)) END),40) AS `marketCode`,SUBSTRING(MAX(CASE WHEN `maketing_department_name` IS NOT NULL AND CAST(`maketing_department_name` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(id AS CHAR),20,'0')),CAST(`maketing_department_name` AS CHAR)) END),40) AS `maketing_department_name`,SUBSTRING(MAX(CASE WHEN `officeCode` IS NOT NULL AND CAST(`officeCode` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(id AS CHAR),20,'0')),CAST(`officeCode` AS CHAR)) END),40) AS `officeCode`,SUBSTRING(MAX(CASE WHEN `office_name` IS NOT NULL AND CAST(`office_name` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(id AS CHAR),20,'0')),CAST(`office_name` AS CHAR)) END),40) AS `office_name`,SUBSTRING(MAX(CASE WHEN `industryId` IS NOT NULL AND CAST(`industryId` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(id AS CHAR),20,'0')),CAST(`industryId` AS CHAR)) END),40) AS `industryId`,SUBSTRING(MAX(CASE WHEN `industry_name` IS NOT NULL AND CAST(`industry_name` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(id AS CHAR),20,'0')),CAST(`industry_name` AS CHAR)) END),40) AS `industry_name`,SUBSTRING(MAX(CASE WHEN `usernamec` IS NOT NULL AND CAST(`usernamec` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(id AS CHAR),20,'0')),CAST(`usernamec` AS CHAR)) END),40) AS `usernamec`,SUBSTRING(MAX(CASE WHEN `marketing_representative_name` IS NOT NULL AND CAST(`marketing_representative_name` AS CHAR)<>'' THEN CONCAT(CONCAT(COALESCE(LEFT(CAST(update_time AS CHAR),19),'1000-01-01 00:00:00'),LPAD(CAST(id AS CHAR),20,'0')),CAST(`marketing_representative_name` A