SELECT * FROM (SELECT b.*,p.packdate AS shipment_time,f.contract_code AS contract_no, CASE WHEN COALESCE(b.rma_no,'')<>'' THEN 'UNCLASSIFIED' ELSE 'SHIPMENT' END AS event_type, CASE WHEN COALESCE(b.rma_no,'')<>'' THEN 1 ELSE 0 END AS rma_marked, TRIM(b.item) AS item_key, fi.itemname AS product_model, fi.describe_ AS product_name FROM fb_shipment_barcode b LEFT JOIN fb_shipment p ON p.packlist_id=b.pack_id LEFT JOIN fb_contract f ON f.contract_id=p.con_id LEFT JOIN (SELECT TRIM(item) AS fb_item, MAX(itemname) AS itemname, MAX(describe_) AS describe_ FROM fb_items GROUP BY TRIM(item)) fi ON fi.fb_item = TRIM(b.item)) function_sample WHERE `id` IS NOT NULL AND TRIM(CAST(`id` AS CHAR)) <> '' ORDER BY `id` LIMIT 20000;

-- H035/PACKAGE task=2101875784728625154 version=1 adapter=TABLE_MAPPING
-- source=C:/Users/user/Documents/Codex/2026-10-08/c-users-user-documents-codex-2026/work/native-followup-private/existing-sync-task-inventory-20261013.json
-- parameter-summary={"count": 0, "namePatterns": {}, "scopeParameters": {}}
SELECT * FROM (SELECT * FROM `fb_shipment`) function_sample WHERE `packlist_id` IS NOT NULL AND TRIM(CAST(`packlist_id` AS CHAR)) <> '' ORDER BY `packlist_id` LIMIT 20000;

-- H036/CONTRACT task=2101875784317583361 version=4 adapter=TABLE_MAPPING
-- source=C:/Users/user/Documents/Codex/2026-10-08/c-users-user-documents-codex-2026/work/native-followup-private/existing-sync-task-inventory-20261013.json
-- parameter-summary={"count": 0, "namePatterns": {}, "scopeParameters": {}}
SELECT function_sample.*, CASE WHEN company_code='01' THEN '001' ELSE company_code END AS normalized_company_code FROM (SELECT e.*,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`currency_name` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`currency_name` IS NOT NULL AND CAST(r.`currency_name` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `currency_name`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`currency_name` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`currency_name` IS NOT NULL AND CAST(r.`currency_name` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `currency_code`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`contract_money_amount` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`contract_money_amount` IS NOT NULL AND CAST(r.`contract_money_amount` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `contract_amount`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`contract_create_date` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`contract_create_date` IS NOT NULL AND CAST(r.`contract_create_date` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `contract_create_time`,CASE WHEN u.company_code IS NOT NULL THEN COALESCE((SELECT s.`project_name` FROM fb_contract s WHERE s.contract_code=e.contract_no AND s.`project_name` IS NOT NULL AND s.`project_name`<>'' ORDER BY s.contract_id DESC LIMIT 1),(SELECT r.`project_name` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`project_name` IS NOT NULL AND CAST(r.`project_name` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1)) ELSE NULL END AS `project_name`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`projectCode` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`projectCode` IS NOT NULL AND CAST(r.`projectCode` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `project_code`,CASE WHEN u.company_code IS NOT NULL THEN COALESCE((SELECT s.`marketCode` FROM fb_contract s WHERE s.contract_code=e.contract_no AND s.`marketCode` IS NOT NULL AND s.`marketCode`<>'' ORDER BY s.contract_id DESC LIMIT 1),(SELECT r.`marketCode` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`marketCode` IS NOT NULL AND CAST(r.`marketCode` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1)) ELSE NULL END AS `market_code`,CASE WHEN u.company_code IS NOT NULL THEN COALESCE((SELECT s.`marketName` FROM fb_contract s WHERE s.contract_code=e.contract_no AND s.`marketName` IS NOT NULL AND s.`marketName`<>'' ORDER BY s.contract_id DESC LIMIT 1),(SELECT r.`maketing_department_name` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`maketing_department_name` IS NOT NULL AND CAST(r.`maketing_department_name` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1)) ELSE NULL END AS `market_name`,CASE WHEN u.company_code IS NOT NULL THEN COALESCE((SELECT s.`office_code` FROM fb_contract s WHERE s.contract_code=e.contract_no AND s.`office_code` IS NOT NULL AND s.`office_code`<>'' ORDER BY s.contract_id DESC LIMIT 1),(SELECT r.`officeCode` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`officeCode` IS NOT NULL AND CAST(r.`officeCode` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1)) ELSE NULL END AS `department_code`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`office_name` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`office_name` IS NOT NULL AND CAST(r.`office_name` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `department_name`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`industryId` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`industryId` IS NOT NULL AND CAST(r.`industryId` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `industry_code`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`industry_name` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`industry_name` IS NOT NULL AND CAST(r.`industry_name` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `industry_name`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`usernamec` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`usernamec` IS NOT NULL AND CAST(r.`usernamec` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `marketing_representative_code`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`marketing_representative_name` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`marketing_representative_name` IS NOT NULL AND CAST(r.`marketing_representative_name` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `marketing_representative_name`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT r.`usernamec2` FROM sms_ofst_contract_head_sap r WHERE r.contract_num=e.contract_no AND r.`usernamec2` IS NOT NULL AND CAST(r.`usernamec2` AS CHAR)<>'' ORDER BY r.update_time DESC,r.id DESC LIMIT 1) ELSE NULL END AS `secondary_representative_code`,CASE WHEN u.company_code IS NOT NULL THEN (SELECT s.`systemName` FROM fb_contract s WHERE s.contract_code=e.contract_no AND s.`systemName` IS NOT NULL AND s.`systemName`<>'' ORDER BY s.contract_id DESC LIMIT 1) ELSE NULL END AS `system_name` FROM (SELECT MIN(id) AS id,compCode AS company_code,contractNo AS contract_no,MIN(customerCode) AS customer_code,MIN(customerName) AS customer_name, CASE WHEN COUNT(DISTINCT NULLIF(customerCode,''))>1 OR COUNT(DISTINCT NULLIF(customerName,''))>1 THEN 'CONTRACT_CUSTOMER_CONFLICT' ELSE NULL END AS migration_issue FROM pm_order_data_from_erp WHERE contractNo IS NOT NULL AND contractNo<>'' AND compCode IS NOT NULL AND compCode<>'' GROUP BY compCode,contractNo) e LEFT JOIN (SELECT contractNo, MIN(compCode) AS company_code FROM pm_order_data_from_erp WHERE compCode IS NOT NULL AND compCode <> '' GROUP BY contractNo HAVING COUNT(DISTINCT compCode)=1) u ON u.contractNo=e.contract_no) function_sample WHERE `id` IS NOT NULL AND TRIM(CAST(`id` AS CHAR)) <> '' ORDER BY `id` LIMIT 20000;

-- H037/SHIPMENT_CONTRACT task=2101857698189352962 version=5 adapter=TABLE_MAPPING
-- source=C:/Users/user/Documents/Codex/2026-10-08/c-users-user-documents-codex-2026/work/native-followup-private/existing-sync-task-inventory-20261013.json
-- parameter-summary={"count": 0, "namePatterns": {}, "scopeParameters": {}}
SELECT function_sample.*, CASE WHEN company_code='01' THEN '001' ELSE company_code END AS normalized_company_code FROM (SELECT f.*, e.company_code FROM fb_contract f LEFT JOIN (SELECT contractNo, MIN(compCode) AS company_code FROM pm_order_data_from_erp WHERE compCode IS NOT NULL AND compCode <> '' GROUP BY contractNo HAVING COUNT(DISTINCT compCode)=1) e ON e.contractNo=f.contract_code ORDER BY f.contract_id) function_sample WHERE `contract_id` IS NOT NULL AND TRIM(CAST(`contract_id` AS CHAR)) <> '' ORDER BY `contract_id` LIMIT 20000;

-- H038/EXECUTION_ORDER task=2101625228492091393 version=8 adapter=DPPMS_CRM_EXECUTION_ORDER
-- source=C:/Users/user/Documents/Codex/2026-10-08/c-users-user-documents-codex-2026/work/native-followup-private/existing-sync-task-inventory-20261013.json
-- parameter-summary={"count": 0, "namePatterns": {}, "scopeParameters": {}}
SELECT r.id, r.orderExecNumber, r.dataSource, r.projectCode, r.projectName,
  r.salesManCode, r.salesManName, r.marketCode, r.marketName, r.systemId, r.systemName,
  r.expendId, r.expendName, r.industryId, r.industryName, r.officeCode, r.officeName,
  r.serviceTypeName, r.channelName, r.engineeFee, r.objId, r.applyType, r.corporationCode,
  r.customerProjectName, r.finalCustomerName, r.agentName, r.majorProjectLevel,
  r.projectMoney, r.submitTime, r.predBidDate, r.linkmanName, r.linkmanTel,
  latest.id AS canonicalId, latest.orderExecNumber AS canonical_orderExecNumber,
  latest.dataSource AS canonical_dataSource, latest.projectCode AS canonical_projectCode,
  latest.projectName AS canonical_projectName, latest.salesManCode AS canonical_salesManCode,
  latest.salesManName AS canonical_salesManName, latest.marketCode AS canonical_marketCode,
  latest.marketName AS canonical_marketName, latest.systemId AS canonical_systemId,
  latest.systemName AS canonical_systemName, latest.expendId AS canonical_expendId,
  latest.expendName AS canonical_expendName, latest.industryId AS canonical_industryId,
  latest.industryName AS canonical_industryName, latest.officeCode AS canonical_officeCode,
  latest.officeName AS canonical_officeName, latest.serviceTypeName AS canonical_serviceTypeName,
  latest.channelName AS canonical_channelName, latest.engineeFee AS canonical_engineeFee,
  latest.objId AS canonical_objId, latest.applyType AS canonical_applyType,
  latest.corporationCode AS canonical_corporationCode, latest.customerProjectName AS canonical_customerProjectName,
  latest.finalCustomerName AS canonical_finalCustomerName, latest.agentName AS canonical_agentName,
  latest.majorProjectLevel AS canonical_majorProjectLevel, latest.projectMoney AS canonical_projectMoney,
  latest.submitTime AS canonical_submitTime, latest.predBidDate AS canonical_predBidDate,
  latest.linkmanName AS canonical_linkmanName, latest.linkmanTel AS canonical_linkmanTel
FROM pm_project_property_from_sms r
JOIN (
  SELECT CAST(dataSource AS BINARY) AS systemKey, CAST(orderExecNumber AS BINARY) AS executionKey, MAX(id) AS canonicalId
  FROM pm_project_property_from_sms
  GROUP BY CAST(dataSource AS BINARY), CAST(orderExecNumber AS BINARY)
) selected ON selected.systemKey <=> CAST(r.dataSource AS BINARY)
  AND selected.executionKey <=> CAST(r.orderExecNumber AS BINARY)
JOIN pm_project_property_from_sms latest ON latest.id=selected.canonicalId;

-- H039/ACCEPTANCE task=2101613039156846593 version=0 adapter=PAYMENT_PLAN_ACCEPTANCE
-- source=C:/Users/user/Documents/Codex/2026-10-08/c-users-user-documents-codex-2026/work/native-followup-private/existing-sync-task-inventory-20261013.json
-- parameter-summary={"count": 0, "namePatterns": {}, "scopeParameters": {}}
SELECT pps.*, CASE WHEN (SELECT COUNT(*) FROM codex_detail_event_source fbd WHERE fbd.dataTypeCode = '09' AND fbd.basicDataName = pps.referenceEventName AND fbd.effectiveFrom <= NOW() AND (fbd.effectiveTo > NOW() OR fbd.effectiveTo IS NULL)) = 1 THEN pps.referenceEventName ELSE NULL END AS validReferenceEvent FROM codex_detail_payment_source pps;

-- H040/ORDER task=2101587859478949890 version=27 adapter=DPPMS_ERP_ORDER
-- source=C:/Users/user/Documents/Codex/2026-10-08/c-users-user-documents-codex-2026/work/native-followup-private/existing-sync-task-inventory-20261013.json
-- parameter-summary={"count": 2, "namePatterns": {"reviewedSourceIds": 1, "unreviewedSourceIds": 1}, "scopeParameters": {}}
-- Existing order identities only. The task supplies reviewed fingerprints and the exact approved source scope.
-- Every selected original keeps its full sixteen source columns. Conflicting originals stay in separate evidence.
SELECT r.*, g.migrationVersion,
       CASE WHEN g.payloadVariants>1 THEN 'DUPLICATE_BUSINESS_KEY_CONFLICT' ELSE NULL END AS migrationIssue,
       SHA2(CAST(JSON_ARRAY(r.id,r.orderNumber,r.contractNo,r.orderExecNumber,r.orderCreateTime,
           r.customerRequireTime,r.customerCode,r.customerName,r.projectName,r.orderComment,r.orderType,
           r.compCode,r.salesType,r.source,r.customInfo,r.syncTime) AS CHAR),256) AS originalSourceFingerprint,
       JSON_OBJECT('id',r.id,'orderNumber',r.orderNumber,'contractNo',r.contractNo,'orderExecNumber',r.orderExecNumber,
           'orderCreateTime',r.orderCreateTime,'customerRequireTime',r.customerRequireTime,'customerCode',r.customerCode,
           'customerName',r.customerName,'projectName',r.projectName,'orderComment',r.orderComment,'orderType',r.orderType,
           'compCode',r.compCode,'salesType',r.salesType,'source',r.source,'customInfo',r.customInfo,'syncTime',r.syncTime) AS originalSourceFields
FROM pm_order_data_from_erp r
JOIN (SELECT source,compCode,orderType,orderNumber,MAX(syncTime) AS migrationVersion,
             COUNT(DISTINCT JSON_ARRAY(orderCreateTime,customerRequireTime,customerCode,customerName,projectName,
                 orderComment,salesType,customInfo,contractNo,orderExecNumber)) AS payloadVariants
      FROM pm_order_data_from_erp GROUP BY source,compCode,orderType,orderNumber) g
  ON r.source <=> g.source AND r.compCode <=> g.compCode AND r.orderType <=> g.orderType AND r.orderNumber <=> g.orderNumber
WHERE (:reviewedSourceIds='' OR FIND_IN_SET(r.id,:reviewedSourceIds))
  AND (:unreviewedSourceIds='' OR NOT FIND_IN_SET(r.id,:unreviewedSourceIds))
;

-- H040/LINE task=2101587859478949890 version=27 adapter=DPPMS_ERP_ORDER
-- source=C:/Users/user/Documents/Codex/2026-10-08/c-users-user-documents-codex-2026/work/native-followup-private/existing-sync-task-inventory-20261013.json
-- parameter-summary={"count": 0, "namePatterns": {}, "scopeParameters": {}}
SELECT r.*,g.migrationVersion,CASE WHEN g.payloadVariants > 1 THEN 'DUPLICATE_BUSINESS_KEY_CONFLICT' ELSE NULL END AS migrationIssue ,EXISTS (SELECT 1 FROM pm_order_data_from_erp h WHERE h.source=r.source AND h.compCode=r.compCode AND h.orderType=r.lineType AND h.orderNumber=r.orderNumber GROUP BY h.source,h.compCode,h.orderType,h.orderNumber HAVING MAX(h.syncTime) IS NOT NULL AND COUNT(DISTINCT JSON_ARRAY(h.orderCreateTime,h.customerRequireTime,h.customerCode,h.customerName,h.projectName,h.orderComment,h.salesType,h.customInfo,h.contractNo,h.orderExecNumber))=1) AS migrationParentExists FROM pm_order_line_from_erp r JOIN (SELECT source,compCode,lineType,orderNumber,lineNum,MAX(syncTime) AS migrationVersion,COUNT(DISTINCT JSON_ARRAY(itemCode,itemDesc,orderQuantity,openQuantity,bundleCode,warrantyMonth,profitCenter,realOrderExecNumber,customInfo)) AS payloadVariants FROM pm_order_line_from_erp GROUP BY source,compCode,lineType,orderNumber,lineNum) g ON r.source <=> g.source AND r.compCode <=> g.compCode AND r.lineType <=> g.lineType AND r.orderNumber <=> g.orderNumber AND r.lineNum <=> g.lineNum WHERE 1=0;

